/// <reference types="node" />
import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { expect, it } from 'vitest'

// docs/openapi.json is generated by the backend; src/api/schema.d.ts is generated from it.
// If someone changes the API and forgets `npm run gen:api`, this fails.
it('src/api/schema.d.ts is up to date with docs/openapi.json', () => {
  const dir = mkdtempSync(join(tmpdir(), 'schema-check-'))
  try {
    const out = join(dir, 'schema.d.ts')
    execFileSync(
      join(process.cwd(), 'node_modules', '.bin', 'openapi-typescript'),
      [join(process.cwd(), '..', 'docs', 'openapi.json'), '-o', out],
      { stdio: 'pipe' },
    )
    expect(readFileSync(out, 'utf8')).toBe(readFileSync(join(process.cwd(), 'src', 'api', 'schema.d.ts'), 'utf8'))
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
})
